Map diskMap  = new HashMap();
Map jvmMap   = new HashMap();
Map shardMap = new HashMap();
Map loadMap  = new HashMap();
Map regMap   = new HashMap();

for (def b : ctx.payload.disk_forecast.aggregations.by_cluster.buckets)
  diskMap[b.key]  = b.peak.value != null ? ((Number)b.peak.value).doubleValue() : 0.0;
for (def b : ctx.payload.jvm_forecast.aggregations.by_cluster.buckets)
  jvmMap[b.key]   = b.peak.value != null ? ((Number)b.peak.value).doubleValue() : 0.0;
for (def b : ctx.payload.shard_forecast.aggregations.by_cluster.buckets)
  shardMap[b.key] = b.peak.value != null ? ((Number)b.peak.value).doubleValue() : 0.0;
for (def b : ctx.payload.load_forecast.aggregations.by_cluster.buckets)
  loadMap[b.key]  = b.peak.value != null ? ((Number)b.peak.value).doubleValue() : 0.0;
for (def hit : ctx.payload.registry.hits.hits)
  regMap[hit._source.cluster_uuid] = hit._source;

List clusters = new ArrayList();
for (def uuid : regMap.keySet()) {
  def reg        = regMap[uuid];
  double dtotal  = reg['disk_total_bytes']       != null ? ((Number)reg['disk_total_bytes']).doubleValue()       : 1.0;
  double smax    = reg['shard_max_threshold']    != null ? ((Number)reg['shard_max_threshold']).doubleValue()    : 1000.0;
  double qthresh = reg['write_queue_threshold']  != null ? ((Number)reg['write_queue_threshold']).doubleValue()  : 50.0;

  double diskB    = diskMap.containsKey(uuid)  ? diskMap[uuid]  : 0.0;
  double jvmP     = jvmMap.containsKey(uuid)   ? jvmMap[uuid]   : 0.0;
  double shardC   = shardMap.containsKey(uuid) ? shardMap[uuid] : 0.0;
  double queueD   = loadMap.containsKey(uuid)  ? loadMap[uuid]  : 0.0;

  double diskScore  = dtotal  > 0 ? (diskB  / dtotal)  * 100.0 : 0.0;
  double jvmScore   = jvmP;
  double shardScore = smax    > 0 ? (shardC / smax)    * 100.0 : 0.0;
  double loadScore  = qthresh > 0 ? (queueD / qthresh) * 100.0 : 0.0;

  // Weighted: 0.50*disk + 0.25*jvm + 0.05*shard + 0.20*load
  double total = 0.50*diskScore + 0.25*jvmScore + 0.05*shardScore + 0.20*loadScore;

  Map c = new HashMap();
  c['cluster_id']              = reg['cluster_id'];
  c['cluster_uuid']            = uuid;
  c['disk_used_pct_forecast']  = diskScore;
  c['jvm_heap_pct_forecast']   = jvmScore;
  c['shard_score']             = shardScore;
  c['write_queue_forecast']    = queueD;
  c['load_score']              = loadScore;
  c['total_score']             = total;
  c['alert']                   = total > 80.0;
  clusters.add(c);
}

Map out = new HashMap();
out['scored_at']              = ctx.execution_time.toString();
out['forecast_horizon_hours'] = 24;
out['clusters']               = clusters;
return out;

// Build cluster score map from latest scoring run
Map scoreMap = new HashMap();
def latestDocs = ctx.payload.scores.hits.hits;
if (!latestDocs.isEmpty()) {
  def sc = latestDocs[0]._source['clusters'];
  if (sc != null) {
    for (def c : sc) {
      Map m = new HashMap();
      m.put('total_score', ((Number)c['total_score']).doubleValue());
      m.put('cluster_id',  c['cluster_id']);
      scoreMap.put((String)c['cluster_uuid'], m);
    }
  }
}

// Build per-cluster per-dataset ingest rates from monitoring
Map clusterRates = new HashMap();
for (def cb : ctx.payload.index_rates.aggregations.by_cluster.buckets) {
  String uuid = (String)cb['key'];
  Map dRates  = new HashMap();
  for (def ib : cb['by_index']['buckets']) {
    String iname = (String)ib['key'];
    if (!iname.startsWith('.ds-')) continue;
    String afterDs = iname.substring(4);
    if (!afterDs.startsWith('logs-') && !afterDs.startsWith('metrics-') && !afterDs.startsWith('traces-')) continue;
    String idx = afterDs;
    int p = idx.lastIndexOf('-'); if (p <= 0) continue;
    idx = idx.substring(0, p);
    p   = idx.lastIndexOf('-');  if (p <= 0) continue;
    idx = idx.substring(0, p);
    int fd = idx.indexOf('-');   if (fd <= 0) continue;
    String rest = idx.substring(fd + 1);
    int nd = rest.lastIndexOf('-'); if (nd <= 0) continue;
    String dataset   = rest.substring(0, nd);
    String namespace = rest.substring(nd + 1);
    String key = dataset + '|' + namespace;
    long delta = 0L;
    def tb = ib['over_time']['buckets'];
    if (tb.size() >= 2) {
      def v0 = tb.get(0)['max_total']['value'];
      def v1 = tb.get(tb.size() - 1)['max_total']['value'];
      if (v0 != null && v1 != null) {
        double diff = ((Number)v1).doubleValue() - ((Number)v0).doubleValue();
        if (diff > 0.0) delta = (long)diff;
      }
    }
    long prev = dRates.containsKey(key) ? ((Number)dRates.get(key)).longValue() : 0L;
    dRates.put(key, prev + delta);
  }
  clusterRates.put(uuid, dRates);
}

// Collect ALL data stream rates into a flat list with source cluster info
List allStreams = new ArrayList();
for (def entry : clusterRates.entrySet()) {
  String uuid = (String)entry.getKey();
  Map dRates = (Map)entry.getValue();
  for (def re : dRates.entrySet()) {
    String key = (String)re.getKey();
    long rate = ((Number)re.getValue()).longValue();
    if (rate <= 0L) continue;
    int pi = key.indexOf('|');
    String dataset = pi > 0 ? key.substring(0, pi) : key;
    String namespace = pi > 0 ? key.substring(pi + 1) : 'default';
    Map s = new HashMap();
    s.put('key', key);
    s.put('dataset', dataset);
    s.put('namespace', namespace);
    s.put('rate', rate);
    s.put('source_uuid', uuid);
    allStreams.add(s);
  }
}

// Sort streams by rate descending and take top N
int N = scoreMap.size();
int streamCount = allStreams.size();
for (int i = 0; i < streamCount - 1; i++) {
  for (int j = i + 1; j < streamCount; j++) {
    long rj = ((Number)allStreams.get(j).get('rate')).longValue();
    long ri = ((Number)allStreams.get(i).get('rate')).longValue();
    if (rj > ri) {
      Map tmp = allStreams.get(i);
      allStreams.set(i, allStreams.get(j));
      allStreams.set(j, tmp);
    }
  }
}
int topN = N < streamCount ? N : streamCount;
List topStreams = new ArrayList();
for (int i = 0; i < topN; i++) {
  topStreams.add(allStreams.get(i));
}

// Sort clusters by score ascending (lightest first)
List clusterList = new ArrayList();
for (def entry : scoreMap.entrySet()) {
  Map m = new HashMap();
  m.put('uuid', entry.getKey());
  m.put('cluster_id', ((Map)entry.getValue()).get('cluster_id'));
  m.put('score', ((Number)((Map)entry.getValue()).get('total_score')).doubleValue());
  clusterList.add(m);
}
int clusterCount = clusterList.size();
for (int i = 0; i < clusterCount - 1; i++) {
  for (int j = i + 1; j < clusterCount; j++) {
    double sj = ((Number)clusterList.get(j).get('score')).doubleValue();
    double si = ((Number)clusterList.get(i).get('score')).doubleValue();
    if (sj < si) {
      Map tmp = clusterList.get(i);
      clusterList.set(i, clusterList.get(j));
      clusterList.set(j, tmp);
    }
  }
}

// Phase 1: Greedy assignment
List suggestions = new ArrayList();
Set usedTargets = new HashSet();
Map vacatingMap = new HashMap();
List skippedList = new ArrayList();

for (int i = 0; i < topStreams.size(); i++) {
  Map stream = (Map)topStreams.get(i);
  String sourceUuid = (String)stream.get('source_uuid');
  long streamRate = ((Number)stream.get('rate')).longValue();

  // Find the lightest cluster that hasn't been used as a target yet
  Map bestTarget = null;
  for (def cl : clusterList) {
    String tgtUuid = (String)cl.get('uuid');
    if (usedTargets.contains(tgtUuid)) continue;
    bestTarget = cl;
    break;
  }
  if (bestTarget == null) break;

  String tgtUuid = (String)bestTarget.get('uuid');
  double tgtScore = ((Number)bestTarget.get('score')).doubleValue();
  double srcScore = ((Number)((Map)scoreMap.get(sourceUuid)).get('total_score')).doubleValue();

  // Source same as target: skip for Phase 2
  if (sourceUuid.equals(tgtUuid)) {
    Map skip = new HashMap();
    skip.put('stream', stream);
    skip.put('target_uuid', tgtUuid);
    skip.put('target_score', tgtScore);
    skip.put('source_score', srcScore);
    skippedList.add(skip);
    usedTargets.add(tgtUuid);
    continue;
  }

  // Target lighter than source: create suggestion
  if (tgtScore < srcScore) {
    usedTargets.add(tgtUuid);
    // Track that source cluster is vacating this rate
    long prevVacating = vacatingMap.containsKey(sourceUuid) ? ((Number)vacatingMap.get(sourceUuid)).longValue() : 0L;
    vacatingMap.put(sourceUuid, prevVacating + streamRate);

    String sourceId = (String)((Map)scoreMap.get(sourceUuid)).get('cluster_id');
    String tgtId = (String)bestTarget.get('cluster_id');

    Map sug = new HashMap();
    sug.put('dataset',               stream.get('dataset'));
    sug.put('namespace',             stream.get('namespace'));
    sug.put('source_cluster',        sourceUuid);
    sug.put('source_cluster_id',     sourceId);
    sug.put('suggested_cluster_id',  tgtId);
    sug.put('source_score',          srcScore);
    sug.put('target_score',          tgtScore);
    sug.put('event_rate_1h',         streamRate);
    sug.put('reason',                'Move ' + stream.get('dataset') + ' (' + streamRate + ' evt/hr) from ' + sourceId + ' (score: ' + (int)srcScore + ') to ' + tgtId + ' (score: ' + (int)tgtScore + ').');
    suggestions.add(sug);
  } else {
    // Target heavier: skip for Phase 2
    Map skip = new HashMap();
    skip.put('stream', stream);
    skip.put('target_uuid', tgtUuid);
    skip.put('target_score', tgtScore);
    skip.put('source_score', srcScore);
    skippedList.add(skip);
    usedTargets.add(tgtUuid);
  }
}

// Phase 2: Paired swaps and local dedicated
for (def skip : skippedList) {
  Map stream = (Map)skip.get('stream');
  String sourceUuid = (String)stream.get('source_uuid');
  String tgtUuid = (String)skip.get('target_uuid');
  long streamRate = ((Number)stream.get('rate')).longValue();
  double tgtScore = ((Number)skip.get('target_score')).doubleValue();
  double srcScore = ((Number)skip.get('source_score')).doubleValue();

  // Source same as target: local dedicated pipeline
  if (sourceUuid.equals(tgtUuid)) {
    String sourceId = (String)((Map)scoreMap.get(sourceUuid)).get('cluster_id');
    Map sug = new HashMap();
    sug.put('dataset',               stream.get('dataset'));
    sug.put('namespace',             stream.get('namespace'));
    sug.put('source_cluster',        sourceUuid);
    sug.put('source_cluster_id',     sourceId);
    sug.put('suggested_cluster_id',  sourceId);
    sug.put('source_score',          srcScore);
    sug.put('target_score',          srcScore);
    sug.put('event_rate_1h',         streamRate);
    sug.put('reason',                'Local dedicated pipeline for ' + stream.get('dataset') + ' (' + streamRate + ' evt/hr) on ' + sourceId + '.');
    suggestions.add(sug);
    continue;
  }

  // Target heavier: check paired swap
  if (vacatingMap.containsKey(tgtUuid)) {
    long vacatingRate = ((Number)vacatingMap.get(tgtUuid)).longValue();
    if (vacatingRate > streamRate) {
      // Safe swap: target is losing more rate than this dataset would add
      String sourceId = (String)((Map)scoreMap.get(sourceUuid)).get('cluster_id');
      String tgtId = tgtUuid;
      for (def cl : clusterList) {
        if (((String)cl.get('uuid')).equals(tgtUuid)) {
          tgtId = (String)cl.get('cluster_id');
          break;
        }
      }

      Map sug = new HashMap();
      sug.put('dataset',               stream.get('dataset'));
      sug.put('namespace',             stream.get('namespace'));
      sug.put('source_cluster',        sourceUuid);
      sug.put('source_cluster_id',     sourceId);
      sug.put('suggested_cluster_id',  tgtId);
      sug.put('source_score',          srcScore);
      sug.put('target_score',          tgtScore);
      sug.put('event_rate_1h',         streamRate);
      sug.put('reason',                'Swap ' + stream.get('dataset') + ' (' + streamRate + ' evt/hr) from ' + sourceId + ' (score: ' + (int)srcScore + ') to ' + tgtId + ' (score: ' + (int)tgtScore + ', vacating ' + vacatingRate + ' evt/hr).');
      suggestions.add(sug);
    }
  }
}

Map out = new HashMap();
out.put('suggested_at',   ctx.execution_time.toString());
out.put('clusters_total', N);
out.put('suggestions',    suggestions);
return out;

Map existing = new HashMap();
for (def hit : ctx.payload.existing_registry.hits.hits) {
  def s = hit._source;
  Map m = new HashMap();
  if (s.containsKey('cluster_id'))            m['cluster_id']            = s['cluster_id'];
  if (s.containsKey('cluster_name'))           m['cluster_name']           = s['cluster_name'];
  if (s.containsKey('active'))                 m['active']                 = s['active'];
  if (s.containsKey('dc'))                     m['dc']                     = s['dc'];
  if (s.containsKey('ingest_hosts'))           m['ingest_hosts']           = s['ingest_hosts'];
  if (s.containsKey('ingest_capacity_per_day')) m['ingest_capacity_per_day'] = s['ingest_capacity_per_day'];
  existing[(String)s['cluster_uuid']] = m;
}

// Extract dc from cluster stats node attributes
Map dcMap = new HashMap();
for (def cb : ctx.payload.monitoring_clusters.aggregations.by_cluster.buckets) {
  String uuid = (String)cb.key;
  if (cb.latest_doc.hits.hits.size() > 0) {
    def src = cb.latest_doc.hits.hits[0]._source;
    def esNode = src.elasticsearch;
    if (esNode != null) {
      def stats = esNode.cluster.stats;
      if (stats != null && stats.state != null && stats.state.nodes != null) {
        def nodes = stats.state.nodes;
        for (def nodeEntry : nodes.entrySet()) {
          def nodeVal = nodeEntry.getValue();
          if (nodeVal != null && nodeVal.attributes != null) {
            if (nodeVal.attributes.dc != null) {
              dcMap.put(uuid, (String)nodeVal.attributes.dc);
              break;
            }
            if (nodeVal.attributes.region != null) {
              dcMap.put(uuid, (String)nodeVal.attributes.region);
              break;
            }
          }
        }
      }
    }
  }
}

Map capacityMap = new HashMap();
for (def cb : ctx.payload.node_capacity.aggregations.by_cluster.buckets) {
  String cid = (String)cb.key;
  long totalDisk = 0L;
  long totalHeap = 0L;
  int nodeCount = 0;
  for (def nb : cb.by_node.buckets) {
    if (nb.disk_total.value != null) totalDisk += ((Number)nb.disk_total.value).longValue();
    if (nb.heap_max.value != null)   totalHeap += ((Number)nb.heap_max.value).longValue();
    nodeCount++;
  }
  Map cap = new HashMap();
  cap['disk_total_bytes'] = totalDisk;
  cap['heap_max_bytes']   = totalHeap;
  cap['node_count']       = nodeCount;
  capacityMap[cid] = cap;
}

List clusters = new ArrayList();
for (def b : ctx.payload.monitoring_clusters.aggregations.by_cluster.buckets) {
  String uuid = (String)b.key;
  String name = b.cluster_name.buckets.size() > 0 ? (String)b.cluster_name.buckets[0].key : uuid;

  Map ex  = existing.containsKey(uuid)  ? (Map)existing[uuid]  : new HashMap();
  Map cap = capacityMap.containsKey(uuid) ? (Map)capacityMap[uuid] : new HashMap();

  long diskTotal = cap.containsKey('disk_total_bytes') ? ((Number)cap['disk_total_bytes']).longValue() * 85L / 100L : 0L;
  long heapMax   = cap.containsKey('heap_max_bytes')   ? ((Number)cap['heap_max_bytes']).longValue()   : 0L;
  int  nodeCount = cap.containsKey('node_count')       ? ((Number)cap['node_count']).intValue()        : 0;

  int shardMax = heapMax > 0L
    ? (int)Math.round((double)heapMax / 1073741824.0 * 20.0)
    : 1000;

  long queueThresh = 200L;

  Map c = new HashMap();
  c['cluster_uuid']            = uuid;
  c['cluster_id']              = ex.containsKey('cluster_id')            ? (String)ex['cluster_id']            : uuid;
  c['cluster_name']            = ex.containsKey('cluster_name')           ? (String)ex['cluster_name']           : name;
  c['dc']                      = dcMap.containsKey(uuid)                 ? (String)dcMap[uuid]                 : (ex.containsKey('dc') ? (String)ex['dc'] : '');
  c['disk_total_bytes']        = diskTotal;
  c['heap_max_bytes']          = heapMax;
  c['node_count']             = nodeCount;
  c['shard_max_threshold']    = shardMax;
  c['write_queue_threshold']  = queueThresh;
  c['active']                  = ex.containsKey('active') ? (boolean)ex['active'] : true;
  if (ex.containsKey('ingest_hosts'))            c['ingest_hosts']            = (String)ex['ingest_hosts'];
  if (ex.containsKey('ingest_capacity_per_day')) c['ingest_capacity_per_day'] = ((Number)ex['ingest_capacity_per_day']).longValue();
  clusters.add(c);
}

Map out = new HashMap();
out['clusters'] = clusters;
return out;

// ====== CPM Pipeline Pusher ======
// Reads state from cpm-pipeline-state, renders pipeline configs, and pushes to Logstash

// JSON-escape helper characters
String BS  = Character.toString((char)92);
String DQ  = Character.toString((char)34);
String NL  = Character.toString((char)10);
String CR  = Character.toString((char)13);
String TAB = Character.toString((char)9);

String ts = ctx.execution_time.toString();

// Build registry map
Map registryMap = new HashMap();
for (def hit : ctx.payload.registry.hits.hits) {
  Map src = hit._source;
  String cid = (String)src.cluster_id;
  Map m = new HashMap();
  m.put('cluster_id', cid);
  m.put('cluster_uuid', (String)src.cluster_uuid);
  m.put('cluster_name', src.cluster_name != null ? (String)src.cluster_name : '');
  m.put('ingest_hosts', src.ingest_hosts != null ? (String)src.ingest_hosts : '');
  m.put('dc', src.dc != null ? (String)src.dc : '');
  registryMap.put(cid, m);
}

// Read templates from search results
String kafkaBootstrap = 'kafka:9092';
String dedicatedTpl = '';
long dedicatedConsumerThreads = 1;
Map dedicatedSettings = new HashMap();
if (ctx.payload.template_dedicated.hits.total > 0) {
  for (def hit : ctx.payload.template_dedicated.hits.hits) {
    if ('dedicated'.equals((String)hit._id)) {
      dedicatedTpl = (String)hit._source.template;
      def ct = hit._source.consumer_threads;
      if (ct != null) dedicatedConsumerThreads = ct;
      def kb = hit._source.kafka_bootstrap;
      if (kb != null) kafkaBootstrap = (String)kb;
      def ps = hit._source.pipeline_settings;
      if (ps != null) dedicatedSettings = (Map)ps;
      break;
    }
  }
}
String catchallTpl = '';
long catchallConsumerThreads = 1;
Map catchallSettings = new HashMap();
if (ctx.payload.template_catchall.hits.total > 0) {
  for (def hit : ctx.payload.template_catchall.hits.hits) {
    if ('catchall'.equals((String)hit._id)) {
      catchallTpl = (String)hit._source.template;
      def ct = hit._source.consumer_threads;
      if (ct != null) catchallConsumerThreads = ct;
      def ps = hit._source.pipeline_settings;
      if (ps != null) catchallSettings = (Map)ps;
      break;
    }
  }
}

// Group state entries by pipeline_id
Map pipelineGroups = new HashMap();    // pipeline_id -> List of state entries
Map pipelineTypes = new HashMap();     // pipeline_id -> 'dedicated' or 'catchall'
Map pipelineClusters = new HashMap();  // pipeline_id -> cluster_id
Map pipelineDcs = new HashMap();      // pipeline_id -> dc

for (def hit : ctx.payload.state.hits.hits) {
  Map src = hit._source;
  String pid = (String)src.pipeline_id;
  String ptype = (String)src.pipeline_type;
  String cid = (String)src.cluster_id;
  String dc = src.dc != null ? (String)src.dc : 'default';

  if (!pipelineGroups.containsKey(pid)) {
    pipelineGroups.put(pid, new ArrayList());
    pipelineTypes.put(pid, ptype);
    pipelineClusters.put(pid, cid);
    pipelineDcs.put(pid, dc);
  }
  ((List)pipelineGroups.get(pid)).add(src);
}

// Build pipelines
List pipelines = new ArrayList();

for (def entry : pipelineGroups.entrySet()) {
  String pid = (String)entry.getKey();
  List entries = (List)entry.getValue();
  String ptype = (String)pipelineTypes.get(pid);
  String cid = (String)pipelineClusters.get(pid);
  String dc = (String)pipelineDcs.get(pid);

  Map cluster = (Map)registryMap.get(cid);
  if (cluster == null) continue;
  String ingestHosts = (String)cluster.get('ingest_hosts');
  if (ingestHosts == null || ingestHosts.isEmpty()) continue;
  String clusterName = (String)cluster.get('cluster_name');
  if (clusterName == null || clusterName.isEmpty()) clusterName = cid;
  String groupId = 'cpm-' + clusterName;

  String esHostsStr = DQ + ingestHosts.replace(',', ':9200' + DQ + ',' + DQ) + ':9200' + DQ;
  String apiKeyVar = 'ES_API_KEY_' + cid.toUpperCase().replace('-', '_');

  String config;
  String description;

  if ('dedicated'.equals(ptype)) {
    // Dedicated: single dataset pipeline
    Map first = (Map)entries.get(0);
    String dataset = (String)first.dataset;
    String namespace = first.namespace != null ? (String)first.namespace : 'default';
    String topic = dataset + '-' + namespace;

    config = dedicatedTpl
      .replace('__KAFKA_BOOTSTRAP__', kafkaBootstrap)
      .replace('__TOPIC__', topic)
      .replace('__PIPELINE_ID__', pid)
      .replace('__GROUP_ID__', groupId)
      .replace('__CONSUMER_THREADS__', String.valueOf(dedicatedConsumerThreads))
      .replace('__ES_HOSTS__', esHostsStr)
      .replace('__DATASET__', dataset)
      .replace('__NAMESPACE__', namespace)
      .replace('__API_KEY_VAR__', apiKeyVar);

    description = 'CPM dedicated pipeline to ' + cid + ' (' + dataset + ')';
  } else {
    // Catchall: multiple topics
    String topicsList = '';
    for (int ti = 0; ti < entries.size(); ti++) {
      Map e = (Map)entries.get(ti);
      String topic = (String)e.topic;
      if (ti > 0) topicsList = topicsList + ', ';
      topicsList = topicsList + DQ + topic + DQ;
    }

    config = catchallTpl
      .replace('__KAFKA_BOOTSTRAP__', kafkaBootstrap)
      .replace('__TOPICS_LIST__', topicsList)
      .replace('__CLUSTER_ID__', cid)
      .replace('__GROUP_ID__', groupId)
      .replace('__CONSUMER_THREADS__', String.valueOf(catchallConsumerThreads))
      .replace('__ES_HOSTS__', esHostsStr)
      .replace('__API_KEY_VAR__', apiKeyVar);

    description = 'CPM catch-all pipeline for ' + cid + ' (' + entries.size() + ' datasets)';
  }

  // Build pipeline_settings from template (numbers unquoted, strings quoted)
  Map settings = 'dedicated'.equals(ptype) ? dedicatedSettings : catchallSettings;
  String settingsStr = '';
  int si = 0;
  for (def se : settings.entrySet()) {
    String skey = (String)se.getKey();
    def sval = se.getValue();
    if (si > 0) settingsStr = settingsStr + ',';
    if (sval instanceof Number) {
      settingsStr = settingsStr + DQ + skey + DQ + ':' + String.valueOf(sval);
    } else {
      settingsStr = settingsStr + DQ + skey + DQ + ':' + DQ + String.valueOf(sval) + DQ;
    }
    si++;
  }

  String esc = config.replace(BS, BS + BS).replace(DQ, BS + DQ).replace(NL, BS + 'n').replace(CR, BS + 'r').replace(TAB, BS + 't');

  String body = '{' +
    DQ + 'description' + DQ + ':' + DQ + description + DQ + ',' +
    DQ + 'last_modified' + DQ + ':' + DQ + ts + DQ + ',' +
    DQ + 'pipeline_metadata' + DQ + ':{' + DQ + 'type' + DQ + ':' + DQ + 'logstash_pipeline' + DQ + ',' + DQ + 'version' + DQ + ':1},' +
    DQ + 'pipeline' + DQ + ':' + DQ + esc + DQ + ',' +
    DQ + 'pipeline_settings' + DQ + ':{' + settingsStr + '},' +
    DQ + 'username' + DQ + ':' + DQ + 'cpm' + DQ +
    '}';

  Map p = new HashMap();
  p.put('pipeline_id', pid);
  p.put('body', body);
  pipelines.add(p);
}

Map out = new HashMap();
out.put('pipelines', pipelines);
return out;

// ====== CPM Pipeline Manager (State Builder) ======
// Computes desired state: which dataset goes to which cluster/pipeline
// Outputs: state entries written to cpm-pipeline-state

// Timestamp
String ts = ctx.execution_time.toString();

// Build registry map: cluster_id -> {cluster_uuid, cluster_name, ingest_hosts, dc}
Map registryMap = new HashMap();
for (def hit : ctx.payload.registry.hits.hits) {
  Map src = hit._source;
  String cid = (String)src.cluster_id;
  Map m = new HashMap();
  m.put('cluster_id', cid);
  m.put('cluster_uuid', (String)src.cluster_uuid);
  m.put('cluster_name', src.cluster_name != null ? (String)src.cluster_name : '');
  m.put('ingest_hosts', src.ingest_hosts != null ? (String)src.ingest_hosts : '');
  m.put('dc', src.dc != null ? (String)src.dc : '');
  registryMap.put(cid, m);
}

// ====== DEDICATED PIPELINES (from routing suggestions) ======
List stateEntries = new ArrayList();
Set managedTopics = new HashSet();
Set seenClusters = new HashSet();

def sugDocs = ctx.payload.routing_suggestions.hits.hits;
for (def hit : sugDocs) {
  Map src = hit._source;
  String dataset    = (String)src.dataset;
  String namespace  = src.namespace != null ? (String)src.namespace : 'default';
  String sugCluster = (String)src.suggested_cluster_id;

  if (seenClusters.contains(sugCluster)) continue;
  seenClusters.add(sugCluster);

  Map cluster = (Map)registryMap.get(sugCluster);
  if (cluster == null) continue;
  String dc = (String)cluster.get('dc');
  if (dc == null || dc.isEmpty()) dc = 'default';

  String topic = dataset + '-' + namespace;
  String pipelineId = dc + '_cpm-dedicated-' + sugCluster;
  managedTopics.add(topic);

  Map st = new HashMap();
  st.put('dataset', dataset);
  st.put('namespace', namespace);
  st.put('pipeline_type', 'dedicated');
  st.put('pipeline_id', pipelineId);
  st.put('cluster_id', sugCluster);
  st.put('dc', dc);
  st.put('topic', topic);
  st.put('updated_at', ts);
  stateEntries.add(st);
}

// ====== READ EXISTING STATE (source of truth for catchall assignments) ======
Map stateCatchallTopics = new HashMap();
Set stateAllTopics = new HashSet();

if (ctx.payload.existing_state != null && ctx.payload.existing_state.hits != null) {
  for (def hit : ctx.payload.existing_state.hits.hits) {
    Map src = hit._source;
    String ptype = (String)src.pipeline_type;
    String topic = (String)src.topic;
    String cid = (String)src.cluster_id;

    if ('dedicated'.equals(ptype)) continue;
    if (managedTopics.contains(topic)) continue;

    if (!stateCatchallTopics.containsKey(cid)) {
      stateCatchallTopics.put(cid, new ArrayList());
    }
    ((List)stateCatchallTopics.get(cid)).add(topic);
    stateAllTopics.add(topic);
  }
}

// ====== DISCOVER NEW DATASETS FROM MONITORING (fallback) ======
Map datasetClusterMap = new HashMap();
def rateBuckets = ctx.payload.dataset_rates.aggregations.by_cluster.buckets;
for (def cb : rateBuckets) {
  String uuid = (String)cb.key;
  for (def ib : cb.by_index.buckets) {
    String iname = (String)ib.key;
    if (!iname.startsWith('.ds-logs-')) continue;
    String afterDs = iname.substring(4);
    String idx = afterDs;
    int p = idx.lastIndexOf('-'); if (p <= 0) continue;
    idx = idx.substring(0, p);
    p = idx.lastIndexOf('-'); if (p <= 0) continue;
    idx = idx.substring(0, p);
    int fd = idx.indexOf('-'); if (fd <= 0) continue;
    String rest = idx.substring(fd + 1);
    int nd = rest.lastIndexOf('-'); if (nd <= 0) continue;
    String dataset = rest.substring(0, nd);
    String ns = rest.substring(nd + 1);
    String topic = dataset + '-' + ns;
    if (managedTopics.contains(topic)) continue;
    if (stateAllTopics.contains(topic)) continue;
    Map cl = (Map)registryMap.get(uuid);
    if (cl != null) {
      Map dm = new HashMap();
      dm.put('cluster_id', (String)cl.get('cluster_id'));
      dm.put('namespace', ns);
      datasetClusterMap.put(dataset, dm);
    }
  }
}

// ====== MERGE: state + new monitoring data ======
Map clusterTopics = new HashMap(stateCatchallTopics);
for (def entry : datasetClusterMap.entrySet()) {
  String dataset = (String)entry.getKey();
  Map dm = (Map)entry.getValue();
  String cid = (String)dm.get('cluster_id');
  String ns = (String)dm.get('namespace');
  String topic = dataset + '-' + ns;
  if (!clusterTopics.containsKey(cid)) {
    clusterTopics.put(cid, new ArrayList());
  }
  ((List)clusterTopics.get(cid)).add(topic);
}

// ====== CATCHALL STATE ENTRIES ======
for (def ctEntry : clusterTopics.entrySet()) {
  String cid = (String)ctEntry.getKey();
  List topics = (List)ctEntry.getValue();
  Map cluster = (Map)registryMap.get(cid);
  if (cluster == null) continue;
  String dc = (String)cluster.get('dc');
  if (dc == null || dc.isEmpty()) dc = 'default';
  String pipelineId = dc + '_cpm-catchall-' + cid;

  for (int si = 0; si < topics.size(); si++) {
    String topic = (String)topics.get(si);
    int lastDash = topic.lastIndexOf('-');
    String dsName = lastDash > 0 ? topic.substring(0, lastDash) : topic;
    String ns = lastDash > 0 ? topic.substring(lastDash + 1) : 'default';
    Map st = new HashMap();
    st.put('dataset', dsName);
    st.put('namespace', ns);
    st.put('pipeline_type', 'catchall');
    st.put('pipeline_id', pipelineId);
    st.put('cluster_id', cid);
    st.put('dc', dc);
    st.put('topic', topic);
    st.put('updated_at', ts);
    stateEntries.add(st);
  }
}

Map out = new HashMap();
out.put('state', stateEntries);
return out;
